class Solution { public: vector<int> minInterval(vector<vector<int>>& intervals,vector<int>& queries){sort(intervals.begin(),intervals.end());vector<int> order(queries.size());iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int a,int b){return queries[a]<queries[b];});priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> heap;vector<int> answer(queries.size(),-1);int next=0;for(int index:order){int value=queries[index];while(next<(int)intervals.size()&&intervals[next][0]<=value){heap.push({intervals[next][1]-intervals[next][0]+1,intervals[next][1]});++next;}while(!heap.empty()&&heap.top().second<value)heap.pop();if(!heap.empty())answer[index]=heap.top().first;}return answer;} };
